import multiprocessing as mp
from multiprocessing import Queue, Manager
from functools import partial

def worker(name, que):
    que.put("%d is done" % name)

def put(name, queue):
    queue.put(name)

def main():
    m = Manager()
    q = m.Queue()
    pool = mp.Pool(processes=3)
    map_result = pool.map(partial(put, queue=q), range(5))
    while not q.empty():
        if q.empty():
            break
        print(q.get())

if __name__ == '__main__':
    main()
